""" prints number of seconds in hours:minutes:seconds format"""
def get_hms_for_seconds(seconds: Any) -> object {
    (m, s) = divmod(seconds, 60);
    (h, m) = divmod(m, 60);
    hms = "%d hours: %02d min: %02d sec" % (h, m, s);
    return hms;
}

